/** Reads official in-game JSON exports in Node. Private save files are unsupported. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    decodePlayerInfoSaveBytes, decodePlayerInfoSaveBytesAsync
 * depends    src/node/types, src/save-decoder, src/save/battle/history
 * used by    src/calculators/specs.generated, src/node/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { listImportableBattleRuns } from '../save/battle/history'
import { decodeInflatedSave } from '../save-decoder'
import type { PlayerInfoSaveDecodeResult } from './types'

/** Parse an External Tools Export; encrypted and legacy binary saves are rejected. */
export function decodePlayerInfoSaveBytes(input: Uint8Array | Buffer | ArrayBuffer): PlayerInfoSaveDecodeResult {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input)
  const parsedRoot = decodeInflatedSave(bytes)
  return { parsedRoot, wasGzip: false, battleRunCount: listImportableBattleRuns(parsedRoot).length }
}

/** Asynchronous adapter for the same official-export reader. */
export async function decodePlayerInfoSaveBytesAsync(input: Uint8Array | Buffer | ArrayBuffer): Promise<PlayerInfoSaveDecodeResult> {
  return decodePlayerInfoSaveBytes(input)
}
